import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';
import { hmacHex, timingSafeEqual } from '../../lib/hash';


export class AuthorizeNetGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "Authorize.Net",
      slug: "authorize-net",
      version: '1.0.0',
      description: "Authorize.Net payment gateway integration for EdgePay",
      author: 'EdgePay Gateway Suite (AGPLv3)',
      type: 'gateway',
      supported_currencies: [],
      capabilities: ["verification", "webhook"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "api_login_id", label: "API Login ID", type: "text" as const, required: true },
      { name: "transaction_key", label: "Transaction Key", type: "password" as const, required: true },
      { name: "signature_key", label: "Signature Key", type: "password" as const, required: true },
    ];
  }

  async initiate(_params: InitiateParams, _credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    return { form_html: "<div class=\"op-alert op-alert-danger\">Failed to initialize Authorize.Net stream.</div>" };
  }

  async verify(callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["gateway_trx_id"] ?? '') === '') {
      return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
    }
    const loginId = String(credentials["api_login_id"] ?? '');
    const transKey = String(credentials["transaction_key"] ?? '');
    const endpoint = (String(credentials.mode ?? '') === String("live")) ? ("https://api.authorize.net/xml/v1/request.api") : ("https://apitest.authorize.net/xml/v1/request.api");
    const payload = { ["getTransactionDetailsRequest"]: { ["merchantAuthentication"]: { ["name"]: loginId, ["transactionKey"]: transKey }, ["transId"]: cb["gateway_trx_id"] } };
    const res = await gwJson({
      url: endpoint,
      method: 'POST',
      headers: { ["User-Agent"]: "EdgePay Gateway Client/1.0.0" },
      body: JSON.stringify(payload),
      timeoutMs: 10000,
    });
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const d = res.data as Record<string, unknown>;
    const ok = (res.data !== null) && (String((((((d) as Record<string, unknown>)["transaction"]) as Record<string, unknown> | undefined)?.["transactionStatus"] ?? "")) === String("settledSuccessfully"));
    return {
          success: ok,
          gateway_trx_id: String(((cb) as Record<string, unknown>)["gateway_trx_id"] ?? ''),
          amount: (String(String(((((d) as Record<string, unknown>)["transaction"]) as Record<string, unknown> | undefined)?.["authAmount"] ?? '') ?? '') || null) as string | null,
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
        };
  }

  async verifyWebhook(input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    const credentials = input.credentials;
    const secret = credentials["signature_key"] ?? '';
    if (secret === '') return false; // fail-closed
    const provided = input.headers["X-Anet-Signature"] ?? '';
    if (provided === '') return false;
    const expected = await hmacHex('SHA-512', input.rawBody, secret);
    return timingSafeEqual(expected, provided);
  }
}
